sys_script.script:
(function executeRule(current, previous /* null when async */) {

    // Only validate an existing record whose status is actually changing
    if (!previous || !current.handoff_status.changes()) {
        return;
    }

    var oldStatus = previous.getValue('handoff_status');
    var newStatus = current.getValue('handoff_status');

    // Completed and Cancelled are terminal states
    if (oldStatus == 'Completed' || oldStatus == 'Cancelled') {

        gs.addErrorMessage(
            'A handoff that is already ' +
            oldStatus +
            ' cannot be moved to another status.'
        );

        current.setAbortAction(true);
        return;
    }

    // Pending can move to In Progress or Cancelled
    if (oldStatus == 'Pending') {

        if (newStatus != 'In Progress' &&
            newStatus != 'Cancelled') {

            gs.addErrorMessage(
                'A Pending handoff can move only to In Progress or Cancelled.'
            );

            current.setAbortAction(true);
            return;
        }
    }

    // In Progress can move to Completed or Cancelled
    if (oldStatus == 'In Progress') {

        if (newStatus != 'Completed' &&
            newStatus != 'Cancelled') {

            gs.addErrorMessage(
                'An In Progress handoff can move only to Completed or Cancelled.'
            );

            current.setAbortAction(true);
            return;
        }
    }

})(current, previous);
